// src/config/NpcType.ts
class NpcType {
  static numDefinitions = 0;
  static idx = null;
  static dat = null;
  static recent = null;
  static recentPos = 0;
  static modelCache = new LruCache(30);
  id = -1;
  name = null;
  desc = null;
  size = 1;
  model = null;
  head = null;
  readyanim = -1;
  walkanim = -1;
  walkanim_b = -1;
  walkanim_r = -1;
  walkanim_l = -1;
  recol_s = null;
  recol_d = null;
  op = null;
  minimap = true;
  vislevel = -1;
  resizeh = 128;
  resizev = 128;
  alwaysontop = false;
  ambient = 0;
  contrast = 0;
  headicon = -1;
  turnspeed = 32;
  static init(config) {
    this.dat = new Packet(config.read("npc.dat"));
    const idx = new Packet(config.read("npc.idx"));
    this.numDefinitions = idx.g2();
    this.idx = new Int32Array(this.numDefinitions);
    let offset = 2;
    for (let id = 0;id < this.numDefinitions; id++) {
      this.idx[id] = offset;
      offset += idx.g2();
    }
    this.recent = new TypedArray1d(20, null);
    for (let id = 0;id < 20; id++) {
      this.recent[id] = new NpcType;
    }
  }
  static list(id) {
    if (!this.recent || !this.idx || !this.dat) {
      throw new Error;
    }
    for (let i = 0;i < 20; i++) {
      const type = this.recent[i];
      if (type && type.id === id) {
        return type;
      }
    }
    this.recentPos = (this.recentPos + 1) % 20;
    const npc = this.recent[this.recentPos] = new NpcType;
    this.dat.pos = this.idx[id];
    npc.id = id;
    npc.decode(this.dat);
    return npc;
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        break;
      }
      if (code === 1) {
        const count = dat.g1();
        this.model = new Uint16Array(count);
        for (let i = 0;i < count; i++) {
          this.model[i] = dat.g2();
        }
      } else if (code === 2) {
        this.name = dat.gjstr();
      } else if (code === 3) {
        this.desc = dat.gjstr();
      } else if (code === 12) {
        this.size = dat.g1b();
      } else if (code === 13) {
        this.readyanim = dat.g2();
      } else if (code === 14) {
        this.walkanim = dat.g2();
      } else if (code === 17) {
        this.walkanim = dat.g2();
        this.walkanim_b = dat.g2();
        this.walkanim_r = dat.g2();
        this.walkanim_l = dat.g2();
      } else if (code >= 30 && code < 40) {
        if (!this.op) {
          this.op = new TypedArray1d(5, null);
        }
        this.op[code - 30] = dat.gjstr();
        if (this.op[code - 30]?.toLowerCase() === "hidden") {
          this.op[code - 30] = null;
        }
      } else if (code === 40) {
        const count = dat.g1();
        this.recol_s = new Uint16Array(count);
        this.recol_d = new Uint16Array(count);
        for (let i = 0;i < count; i++) {
          this.recol_s[i] = dat.g2();
          this.recol_d[i] = dat.g2();
        }
      } else if (code === 60) {
        const count = dat.g1();
        this.head = new Uint16Array(count);
        for (let i = 0;i < count; i++) {
          this.head[i] = dat.g2();
        }
      } else if (code === 90) {
        dat.pos += 2;
      } else if (code === 91) {
        dat.pos += 2;
      } else if (code === 92) {
        dat.pos += 2;
      } else if (code === 93) {
        this.minimap = false;
      } else if (code === 95) {
        this.vislevel = dat.g2();
      } else if (code === 97) {
        this.resizeh = dat.g2();
      } else if (code === 98) {
        this.resizev = dat.g2();
      } else if (code === 99) {
        this.alwaysontop = true;
      } else if (code === 100) {
        this.ambient = dat.g1b();
      } else if (code === 101) {
        this.contrast = dat.g1b() * 5;
      } else if (code === 102) {
        this.headicon = dat.g2();
      } else if (code === 103) {
        this.turnspeed = dat.g2();
      }
    }
  }
  getTempModel(primaryTransformId, secondaryTransformId, seqMask, primaryNextTransformId = -1, primaryTween = 0) {
    let model = NpcType.modelCache.find(BigInt(this.id));
    if (!model && this.model) {
      let ready = false;
      for (let i = 0;i < this.model.length; i++) {
        if (!Model.requestDownload(this.model[i])) {
          ready = true;
        }
      }
      if (ready) {
        return null;
      }
      const models = new TypedArray1d(this.model.length, null);
      for (let i = 0;i < this.model.length; i++) {
        models[i] = Model.load(this.model[i]);
      }
      if (models.length === 1) {
        model = models[0];
      } else {
        model = Model.combineForAnim(models, models.length);
      }
      if (model) {
        if (this.recol_s && this.recol_d) {
          for (let i = 0;i < this.recol_s.length; i++) {
            model.recolour(this.recol_s[i], this.recol_d[i]);
          }
        }
        model.prepareAnim();
        model.calculateNormals(64, 850, -30, -50, -30, true);
        NpcType.modelCache.put(model, BigInt(this.id));
      }
    }
    if (!model) {
      return null;
    }
    const tmp = Model.tempModel;
    tmp.set(model, AnimFrame.shareAlpha(primaryTransformId) && AnimFrame.shareAlpha(secondaryTransformId));
    if (primaryTransformId !== -1 && secondaryTransformId !== -1) {
      tmp.maskAnimate(primaryTransformId, secondaryTransformId, seqMask);
    } else if (primaryTransformId !== -1) {
      tmp.animateTween(primaryTransformId, primaryNextTransformId, primaryTween);
    }
    if (this.resizeh !== 128 || this.resizev !== 128) {
      tmp.resize(this.resizeh, this.resizev, this.resizeh);
    }
    tmp.calcBoundingCylinder();
    tmp.labelFaces = null;
    tmp.labelVertices = null;
    if (this.size === 1) {
      tmp.useAABBMouseCheck = true;
    }
    return tmp;
  }
  getHead() {
    if (!this.head) {
      return null;
    }
    let exists = false;
    for (let i = 0;i < this.head.length; i++) {
      if (!Model.requestDownload(this.head[i])) {
        exists = true;
      }
    }
    if (exists) {
      return null;
    }
    const models = new TypedArray1d(this.head.length, null);
    for (let i = 0;i < this.head.length; i++) {
      models[i] = Model.load(this.head[i]);
    }
    let model;
    if (models.length === 1) {
      model = models[0];
    } else {
      model = Model.combineForAnim(models, models.length);
    }
    if (model && this.recol_s && this.recol_d) {
      for (let i = 0;i < this.recol_s.length; i++) {
        model.recolour(this.recol_s[i], this.recol_d[i]);
      }
    }
    return model;
  }
}

// src/config/IdkType.ts
class IdkType {
  static numDefinitions = 0;
  static list = [];
  part = -1;
  model = null;
  recol_s = new Int32Array(6);
  recol_d = new Int32Array(6);
  head = new Int32Array(5).fill(-1);
  disable = false;
  static init(config) {
    const dat = new Packet(config.read("idk.dat"));
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new IdkType;
      }
      this.list[id].decode(dat);
    }
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        break;
      }
      if (code === 1) {
        this.part = dat.g1();
      } else if (code === 2) {
        const count = dat.g1();
        this.model = new Int32Array(count);
        for (let i = 0;i < count; i++) {
          this.model[i] = dat.g2();
        }
      } else if (code === 3) {
        this.disable = true;
      } else if (code >= 40 && code < 50) {
        this.recol_s[code - 40] = dat.g2();
      } else if (code >= 50 && code < 60) {
        this.recol_d[code - 50] = dat.g2();
      } else if (code >= 60 && code < 70) {
        this.head[code - 60] = dat.g2();
      } else {
        console.log("Error unrecognised config code: ", code);
      }
    }
  }
  checkModel() {
    if (!this.model) {
      return true;
    }
    let ready = true;
    for (let i = 0;i < this.model.length; i++) {
      if (!Model.requestDownload(this.model[i])) {
        ready = false;
      }
    }
    return ready;
  }
  getModelNoCheck() {
    if (!this.model) {
      return null;
    }
    const models = new TypedArray1d(this.model.length, null);
    for (let i = 0;i < this.model.length; i++) {
      models[i] = Model.load(this.model[i]);
    }
    let model;
    if (models.length === 1) {
      model = models[0];
    } else {
      model = Model.combineForAnim(models, models.length);
    }
    for (let i = 0;i < 6 && this.recol_s[i] !== 0; i++) {
      model?.recolour(this.recol_s[i], this.recol_d[i]);
    }
    return model;
  }
  checkHead() {
    let ready = true;
    for (let i = 0;i < this.head.length; i++) {
      if (this.head[i] != -1 && !Model.requestDownload(this.head[i])) {
        ready = false;
      }
    }
    return ready;
  }
  getHeadNoCheck() {
    let count = 0;
    const models = new TypedArray1d(5, null);
    for (let i = 0;i < 5; i++) {
      if (this.head[i] !== -1) {
        models[count++] = Model.load(this.head[i]);
      }
    }
    const model = Model.combineForAnim(models, count);
    for (let i = 0;i < 6 && this.recol_s[i] !== 0; i++) {
      model.recolour(this.recol_s[i], this.recol_d[i]);
    }
    return model;
  }
}

// src/config/SpotType.ts
class SpotType {
  static numDefinitions = 0;
  static list = [];
  static modelCache = new LruCache(30);
  id = 0;
  model = 0;
  anim = -1;
  seq = null;
  recol_s = new Uint16Array(6);
  recol_d = new Uint16Array(6);
  resizeh = 128;
  resizev = 128;
  angle = 0;
  ambient = 0;
  contrast = 0;
  static init(config) {
    const dat = new Packet(config.read("spotanim.dat"));
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new SpotType;
      }
      this.list[id].id = id;
      this.list[id].decode(dat);
    }
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        break;
      }
      if (code === 1) {
        this.model = dat.g2();
      } else if (code === 2) {
        this.anim = dat.g2();
        if (SeqType.list) {
          this.seq = SeqType.list[this.anim];
        }
      } else if (code === 4) {
        this.resizeh = dat.g2();
      } else if (code === 5) {
        this.resizev = dat.g2();
      } else if (code === 6) {
        this.angle = dat.g2();
      } else if (code === 7) {
        this.ambient = dat.g1();
      } else if (code === 8) {
        this.contrast = dat.g1();
      } else if (code >= 40 && code < 50) {
        this.recol_s[code - 40] = dat.g2();
      } else if (code >= 50 && code < 60) {
        this.recol_d[code - 50] = dat.g2();
      } else {
        console.log("Error unrecognised spotanim config code: ", code);
      }
    }
  }
  getTempModel2() {
    let model = SpotType.modelCache.find(BigInt(this.id));
    if (model) {
      return model;
    }
    model = Model.load(this.model);
    if (!model) {
      return null;
    }
    for (let i = 0;i < 6; i++) {
      if (this.recol_s[0] !== 0) {
        model.recolour(this.recol_s[i], this.recol_d[i]);
      }
    }
    SpotType.modelCache.put(model, BigInt(this.id));
    return model;
  }
}

// src/config/VarpType.ts
class VarpType {
  static numDefinitions = 0;
  static list = [];
  clientcode = 0;
  static init(config) {
    const dat = new Packet(config.read("varp.dat"));
    this.numDefinitions = dat.g2();
    this.list = new Array(this.numDefinitions);
    for (let id = 0;id < this.numDefinitions; id++) {
      if (!this.list[id]) {
        this.list[id] = new VarpType;
      }
      this.list[id].decode(dat);
    }
    if (dat.pos != dat.data.length) {
      console.log("varptype load mismatch");
    }
  }
  decode(dat) {
    while (true) {
      const code = dat.g1();
      if (code === 0) {
        break;
      }
      if (code === 1) {
        dat.pos += 1;
      } else if (code === 2) {
        dat.pos += 1;
      } else if (code === 3) {} else if (code === 4) {} else if (code === 5) {
        this.clientcode = dat.g2();
      } else if (code === 6) {} else if (code === 7) {
        dat.pos += 4;
      } else if (code === 8) {} else if (code === 10) {
        dat.gjstr();
      } else if (code === 11) {} else {
        console.log("Error unrecognised config code: ", code);
      }
    }
  }
}

