// src/io/ClientStream.ts
class ClientStream {
  socket;
  wsin;
  wsout;
  closed = false;
  ioerror = false;
  static async openSocket(host, secured) {
    return await new Promise((resolve, reject) => {
      const protocol = secured ? "wss" : "ws";
      const ws = new WebSocket(`${protocol}://${host}`, "binary");
      ws.addEventListener("open", () => {
        resolve(ws);
      });
      ws.addEventListener("error", () => {
        reject(ws);
      });
    });
  }
  constructor(socket) {
    socket.onclose = this.onclose;
    socket.onerror = this.onerror;
    this.wsin = new WebSocketReader(socket, 5000);
    this.wsout = new WebSocketWriter(socket, 5000);
    this.socket = socket;
  }
  get host() {
    return this.socket.url.split("/")[2];
  }
  get port() {
    return parseInt(this.socket.url.split(":")[2], 10);
  }
  get available() {
    return this.closed ? 0 : this.wsin.available;
  }
  write(src, len) {
    if (!this.closed) {
      this.wsout.write(src, len);
    }
  }
  async read() {
    return this.closed ? 0 : await this.wsin.read();
  }
  async readBytes(dst, off, len) {
    if (this.closed) {
      return;
    }
    await this.wsin.readBytes(dst, off, len);
  }
  close() {
    this.closed = true;
    this.socket.close();
    this.wsin.close();
    this.wsout.close();
  }
  onclose = (_event) => {
    if (this.closed) {
      return;
    }
    this.close();
  };
  onerror = (_event) => {
    if (this.closed) {
      return;
    }
    this.ioerror = true;
    this.close();
  };
}

class WebSocketWriter {
  socket;
  limit;
  closed = false;
  ioerror = false;
  constructor(socket, limit) {
    this.socket = socket;
    this.limit = limit;
  }
  write(src, len) {
    if (this.closed) {
      return;
    }
    if (this.ioerror) {
      this.ioerror = false;
      throw new Error;
    }
    if (len > this.limit || src.length > this.limit) {
      throw new Error;
    }
    try {
      this.socket.send(src.slice(0, len));
    } catch (_e) {
      this.ioerror = true;
    }
  }
  close() {
    this.closed = true;
  }
}

class WebSocketEvent {
  bytes;
  position;
  constructor(bytes) {
    this.bytes = bytes;
    this.position = 0;
  }
  get available() {
    return this.bytes.length - this.position;
  }
  get read() {
    return this.bytes[this.position++];
  }
  get len() {
    return this.bytes.length;
  }
}

