  async mainloop() {
    {
      const nowSec = Math.floor(performance.now() / 1000);
      if (this._lastMainLoopLogSec !== nowSec) {
        this._lastMainLoopLogSec = nowSec;
        fetch("/debug-log", { method: "POST", body: "[mainloop] eS:" + this.errorStarted + " eL:" + this.errorLoading + " eH:" + this.errorHost + " ingame:" + this.ingame + " cycle:" + this.loopCycle }).catch(() => {});
      }
    }
    if (this.errorStarted || this.errorLoading || this.errorHost) {
      return;
    }
    this.loopCycle++;
    if (this.ingame && window.DISCORD_RPC_ENABLED && this.localPlayer) {
      const tileX = this.mapBuildBaseX + (this.localPlayer.x >> 7);
      const tileZ = this.mapBuildBaseZ + (this.localPlayer.z >> 7);
      const area = this.getAreaName(tileX, tileZ);
      const level = this.localPlayer.combatLevel;
      const areaChanged = area !== this.discordLastArea;
      const levelChanged = level !== this.discordLastLevel && this.discordLastLevel !== -1;
      const ticksSinceLast = this.loopCycle - this.discordLastUpdate;
      if (areaChanged || levelChanged || ticksSinceLast >= 200) {
        this.discordLastArea = area;
        this.discordLastLevel = level;
        this.discordLastUpdate = this.loopCycle;
        const displayName = this.localPlayer.name ?? this.loginUser;
        fetch("/api/discord/update?details=" + encodeURIComponent(displayName + " (Level " + level + ")") + "&state=" + encodeURIComponent("in " + area)).catch(() => {});
      }
    }
    if (!this.ingame) {
      await this.titleScreenLoop();
    } else {
      try {
        await this.gameLoop();
      } catch (e) {
        fetch("/debug-log", { method: "POST", body: "[mainloop] gameLoop THREW: " + String(e).substring(0, 300) }).catch(() => {});
        throw e;
      }
    }
    await this.onDemandLoop();
  }
  async maindraw() {
    {
      const nowSec = Math.floor(performance.now() / 1000);
      if (this._lastDbgLogSec !== nowSec) {
        this._lastDbgLogSec = nowSec;
        const od = this.onDemand;
        const hdSt = ThreeRenderer.status(false);
        const errFlags = "eS:" + this.errorStarted + " eL:" + this.errorLoading + " eH:" + this.errorHost;
        const msg = [
          errFlags + " ingame:" + this.ingame + " scene:" + this.sceneState + " dc:" + this.drawCycle + " rem:" + (this.onDemand?.remaining() ?? "?"),
          "hd:" + hdSt.enabled + " hdok:" + hdSt.available + " hdreason:" + hdSt.reason,
          "phase:" + (window._mapPhase ?? "-") + " glph:" + (window._glPhase ?? "-") + " mberr:" + (this._mapBuildError ?? "").substring(0, 80)
        ].join(" | ");
        fetch("/debug-log", { method: "POST", body: "[maindraw] " + msg }).catch(() => {});
      }
    }
    if (this.errorStarted || this.errorLoading || this.errorHost) {
      this.drawError();
      return;
    }
    this.drawCycle++;
    if (!this.ingame) {
      await this.titleScreenDraw();
    } else {
      this.gameDraw();
      this.drawXpDrops();
    }
    if (this.isMobile) {
      MobileKeyboard_default.draw();
    }
    this.scrollCycle = 0;
  }
  refresh() {
    this.redrawFrame = true;
  }
  async onDemandLoop() {
    if (!this.onDemand) {
      return;
    }
    await this.onDemand.run();
    while (true) {
      const req = this.onDemand.loop();
      if (req === null) {
        return;
      }
      if (!req.data) {
        continue;
      }
      if (req.archive === 0) {
        Model.unpack(req.file, req.data);
        if ((this.onDemand.getModelUse(req.file) & 98) != 0) {
          this.redrawSidebar = true;
          if (this.chatComId !== -1) {
            this.redrawChatback = true;
          }
        }
      } else if (req.archive === 1) {
        AnimFrame.unpack(req.data);
      } else if (req.archive === 2) {
        if (this.midiSong === req.file) {
          this.saveMidi(req.data, this.midiFading);
        }
      } else if (req.archive === 3) {
        if (this.mapBuildGroundData && this.mapBuildLocationData && this.sceneState === 1) {
          for (let i2 = 0;i2 < this.mapBuildGroundData.length; i2++) {
            if (this.mapBuildGroundFile[i2] == req.file) {
              this.mapBuildGroundData[i2] = req.data;
              if (req.data == null) {
                this.mapBuildGroundFile[i2] = -1;
              }
              break;
            }
            if (this.mapBuildLocationFile[i2] == req.file) {
              this.mapBuildLocationData[i2] = req.data;
              if (req.data == null) {
                this.mapBuildLocationFile[i2] = -1;
              }
              break;
            }
          }
        }
      } else if (req.archive === 93) {
        if (this.onDemand.hasMapLocFile(req.file)) {
          ClientBuild.prefetchLocations(new Packet(req.data), this.onDemand);
        }
      }
    }
  }
  async titleScreenLoop() {
    if (this.loginscreen === 0) {
      let x2 = (this.sWid / 2 | 0) - 80;
      let y = (this.sHei / 2 | 0) + 20;
      y += 20;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginscreen = 3;
        this.loginSelect = 0;
      }
      x2 = (this.sWid / 2 | 0) + 80;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginMes1 = "";
        this.loginMes2 = "Enter your username & password.";
        this.loginscreen = 2;
        this.loginSelect = 0;
      }
    } else if (this.loginscreen === 2) {
      let y = (this.sHei / 2 | 0) - 40;
      y += 30;
      y += 25;
      if (this.mouseClickButton === 1 && this.mouseClickY >= y - 15 && this.mouseClickY < y) {
        this.loginSelect = 0;
      }
      y += 15;
      if (this.mouseClickButton === 1 && this.mouseClickY >= y - 15 && this.mouseClickY < y) {
        this.loginSelect = 1;
      }
      let x2 = (this.sWid / 2 | 0) - 80;
      y = (this.sHei / 2 | 0) + 50;
      y += 20;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        await this.login(this.loginUser, this.loginPass, false);
        if (this.ingame) {
          return;
        }
      }
      x2 = (this.sWid / 2 | 0) + 80;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginscreen = 0;
        this.loginUser = "";
        this.loginPass = "";
      }
      while (true) {
        const key = this.pollKey();
        if (key === -1) {
          return;
        }
        let valid = false;
        for (let i2 = 0;i2 < PixFont.CHARSET.length; i2++) {
          if (String.fromCharCode(key) === PixFont.CHARSET.charAt(i2)) {
            valid = true;
            break;
          }
        }
        if (this.loginSelect === 0) {
          if (key === 8 && this.loginUser.length > 0) {
            this.loginUser = this.loginUser.substring(0, this.loginUser.length - 1);
          }
          if (key === 9 || key === 10 || key === 13) {
            this.loginSelect = 1;
          }
          if (valid) {
            this.loginUser = this.loginUser + String.fromCharCode(key);
          }
          if (this.loginUser.length > 12) {
            this.loginUser = this.loginUser.substring(0, 12);
          }
        } else if (this.loginSelect === 1) {
          if (key === 8 && this.loginPass.length > 0) {
            this.loginPass = this.loginPass.substring(0, this.loginPass.length - 1);
          }
          if (key === 9 || key === 10 || key === 13) {
            this.loginSelect = 0;
          }
          if (valid) {
            this.loginPass = this.loginPass + String.fromCharCode(key);
          }
          if (this.loginPass.length > 20) {
            this.loginPass = this.loginPass.substring(0, 20);
          }
        }
      }
    } else if (this.loginscreen === 3) {
      const x2 = this.sWid / 2 | 0;
      let y = (this.sHei / 2 | 0) + 50;
      y += 20;
      if (this.mouseClickButton === 1 && this.mouseClickX >= x2 - 75 && this.mouseClickX <= x2 + 75 && this.mouseClickY >= y - 20 && this.mouseClickY <= y + 20) {
        this.loginscreen = 0;
      }
    }
  }
